        DomainName       = tostring(column_ifexists("DomainName", "")),
        FileName         = tostring(column_ifexists("FileName", "")),
        FileHashType     = tostring(column_ifexists("FileHashType", "")),
        FileHashValue    = tostring(column_ifexists("FileHashValue", "")),
        CveId            = tostring(column_ifexists("CveId", "")),
        OutbreakId       = tostring(column_ifexists("OutbreakId", "")),
        AlertId          = tostring(column_ifexists("AlertId", "")),
        PolicyId         = tostring(column_ifexists("PolicyId", "")),
        MachineGroupId   = tostring(column_ifexists("MachineGroupId", "")),
        MachineGroupName = tostring(column_ifexists("MachineGroupName", "")),
        PolicyType       = tostring(column_ifexists("PolicyType", "")),
        Platform         = tostring(column_ifexists("Platform", ""))
    | project
        TimeGenerated,
        StreamName       = SourceName,
        EntityId,
        FieldName        = tostring(field),
        OldValue,
        NewValue,
        SnapshotCurrent  = TimeGenerated,
        SnapshotPrevious = TimeGenerated1,
        ChangeType       = case(
            not(FieldInPrevious), "Added",
            not(FieldInCurrent),  "Removed",
            "Modified"
        ),
        // Architecture J.6: canonical Sentinel Entity Type cols preserved for cross-table filters
        HostMdatpId, HostFullName, HostName, HostDnsDomain, HostOSFamily, HostAadId,
        AccountName, AccountUPNSuffix, AccountObjectId, AccountSid,
        IpAddress, Url, DomainName,
        FileName, FileHashType, FileHashValue,
        CveId, OutbreakId, AlertId, PolicyId,
        MachineGroupId, MachineGroupName, PolicyType, Platform
};
MDE_Drift_Maintenance

// === MDE after-hours drift events ===
//
// WHAT: Defender XDR config/inventory/maintenance drift outside 09:00-17:00 UTC or weekends.
// WHEN: Daily SOC after-hours review pack. Especially valuable Mondays (weekend coverage) + post-holiday.
// WHY: Attackers with admin credentials prefer off-hours stealth changes to avoid change-review windows.
//      Common adversary actions: disable EDR (T1562.001), add TABL allow-list indicators (T1562.006),
//      modify suppression rules, change AV exclusions, weaken alert tuning thresholds.
//
// TRIAGE PATH:
//   1. Filter to ChangeType in ('Added','Modified') — high-impact changes (Removed often legitimate cleanup)
//   2. Pivot on EntityId + FieldName — note WHICH config item + WHAT field changed
//   3. Cross-reference with admin SigninLogs at same TimeGenerated to identify the actor
//   4. Validate against approved change tickets in your ITSM/CR system
//   5. If unauthorized: revert + lock admin account + escalate to IR
//
// EXPECTED BASELINE: 0-5 events/week in mature tenants. Sustained >10/week = admin process drift or compromise.
// TUNING: Adjust 9/17 to local business hours. Convert TimeGenerated to local TZ if not UTC-based.
// MITRE: TA0005 Defense Evasion — T1562.001 (most common); T1556 Modify Authentication Process; T1098.
//
// Workbook time-pickers can override lookback/window via {TimeRange:value} — parsers are parameterized.
union (MDE_Drift_Inventory(7d, 1d)), (MDE_Drift_Configuration(7d, 6h)), (MDE_Drift_Maintenance(30d, 7d))
| extend HourOfDay = datetime_part("Hour", TimeGenerated)
| extend DayOfWeek = dayofweek(TimeGenerated)
| where HourOfDay < 9 or HourOfDay >= 17 or DayOfWeek == time(0d) or DayOfWeek == time(6d)

// === MDE config changes by UPN ===
//
// WHAT: Correlates Defender XDR drift with AuditLogs actor UPNs — attributes "who changed what".
// WHEN: Post-incident retrospective, monthly change-control review, audit response, admin compromise investigation.
// WHY: Drift alone isn't actionable — every config change has a responsible actor. UPN attribution enables
//      (a) accountability, (b) lateral-movement-through-admin-accounts detection, (c) ticket validation.
//
// TRIAGE PATH:
//   1. Sort by DriftEvents desc — top UPNs are prolific admins or compromised
//   2. Unknown UPNs ('unknown (no correlating audit)') = SP/API-direct changes; investigate
//   3. High-volume UPNs: cross-ref Streams + Operations against role + change tickets that day
//   4. Suspicious: pivot to SigninLogs for that UPN — check IP/device/risk-state anomalies
//
// EXPECTED BASELINE: 2-5 admin UPNs cover 80%+ drift; 10-20 distinct UPNs total in healthy tenant.
//                    Single UPN with >100 changes/week = over-privileged or compromised.
// MITRE: TA0005 Defense Evasion — T1562 Impair Defenses; TA0004 Privilege Escalation — T1078 Valid Accounts.
//
// Section R++.C B7 fix: drift EntityIds and AuditLogs target identifiers are not reliable
// to join at record level. Original implementation joined on $left.TimeGenerated == $right.AuditTime —
// exact-second equality never matches sub-second granularity → all ActorUpn defaulted to "unknown".
// Fix: bucket both sides by 5-minute bins (matches MDE_ComplianceDashboard.json:76 pattern).
let drift = union
(MDE_Drift_Inventory(7d, 1d)),
(MDE_Drift_Configuration(7d, 6h)),
(MDE_Drift_Exposure(7d, 1h))
| extend DriftBin = bin(TimeGenerated, 5min);
let audits = AuditLogs
| where TimeGenerated > ago(7d)
| where Category in (
'PolicyManagement',
'DefenderXdrSettings',
'Microsoft Defender for Cloud Apps',
'Microsoft Defender for Identity',
'Unified audit',
'Azure Active Directory'
)
| extend ActorUpn = tostring(InitiatedBy.user.userPrincipalName)
| where isnotempty(ActorUpn)
| extend AuditBin = bin(TimeGenerated, 5min)
| project AuditTime = TimeGenerated, AuditBin, ActorUpn, Operation = OperationName, Category, AuditResult = Result;
drift
| join kind=leftouter (audits) on $left.DriftBin == $right.AuditBin
| extend ActorUpn = coalesce(ActorUpn, 'unknown (no correlating audit)')
| summarize DriftEvents = count(),
Streams = make_set(StreamName),
Operations = make_set(Operation)
by ActorUpn
| order by DriftEvents desc

// === MDE custom detection content audit ===
//
// WHAT: Full current KQL text + schedule + enabled state of every tenant custom detection.
// WHEN: Quarterly detection-engineering review; pre/post-migration; compliance evidence; sabotage investigation.
// WHY: Custom detections are SOC's "homegrown" defense layer + high-value attacker targets.
//      Compromised admin can disable detection 2h, run payload, re-enable — only periodic full-text
//      snapshots catch it. This query is the CURRENT TRUTH anchor for diff against git.
//
// TRIAGE PATH:
//   1. Diff Query column against your detection-content git repo — detect drift from canonical
//   2. Each Enabled='False' row: validate against the disabling change-management ticket
//   3. Unfamiliar detection names: investigate author + arg_max date — attacker-planted to mask activity?
//   4. Pair with MdeCustomDetectionEdited.yaml analytic rule to detect changes in addition to current state
//
// EXPECTED BASELINE: 10-50 active detections in mature tenant. Unexplained adds/removes = red flags.
// TUNING: Adjust 30d lookback if Configuration cadence ≠ 6h. Drop arg_max for full version history.
// MITRE: TA0007 Discovery — T1082; TA0005 Defense Evasion — T1562 Impair Defenses (tamper detection).
//
// Time-bounded to last 30d (CustomDetections cadence = Configuration tier 6h, so 30d catches ~120 snapshots;
// arg_max returns latest per EntityId). Without bound, workspace scan is unbounded → expensive query.
Defender_ConfigurationAndSettings_CL | where TimeGenerated > ago(30d) | where SourceName == 'MDE_CustomDetections_CL' | summarize arg_max(TimeGenerated, *) by EntityId | extend Name = tostring(parse_json(RawJson).displayName), Enabled = tostring(parse_json(RawJson).isEnabled), Query = tostring(parse_json(RawJson).queryText), Schedule = tostring(parse_json(RawJson).schedule) | project EntityId, Name, Enabled, Schedule, Query, TimeGenerated

// === MDE exclusion additions (past quarter) ===
//
// WHAT: Every file/path/process exclusion ADDED to AV/EDR policy in last 90 days.
// WHEN: Monthly governance review, post-AV-tuning ticket validation, persistence investigation,
//       after any "we whitelisted that for compatibility" admin claim.
// WHY: Exclusions are #1 EDR-bypass with admin credentials. Adding C:\ProgramData\<malware> to AV
//      exclusion list whitelists everything from scanning — file drops, executes, persists, never seen.
//      Equally common: powershell.exe process exclusion, domain-wide path exclusions during ransomware staging.
//      Each addition needs business justification AND change ticket.
//
// TRIAGE PATH:
//   1. Verify EntityId (policy+scope) + NewValue (path/hash/process) against change-management ticket system
//   2. Unauthorized: investigate Operator (admin) — check SigninLogs for compromised session
//   3. Remove exclusion via Intune/MDE policy
//   4. Hunt malicious files in previously-excluded path: DeviceFileEvents | where FolderPath has '<path>'
//   5. Lock admin account + escalate to IR if confirmed unauthorized
//
// EXPECTED BASELINE: 0-3 additions/quarter mature tenant. Legitimate: dev workstations, vendor compat, perf servers.
//                    Every addition should map to a ticket.
// TUNING: Adjust 90d for SOX/HIPAA quarterly (120d) or weekly governance (7d).
// MITRE: TA0005 Defense Evasion — T1562.001 (primary); TA0003 Persistence — T1546 (payload persistence).
MDE_Drift_Inventory(90d, 1h)
| where StreamName == "MDE_AntivirusPolicy_CL"
| where ChangeType == "Added"
| where FieldName has "exclusion" or FieldName has "Exclusion"
| project TimeGenerated, EntityId, FieldName, NewValue, ChangeType
| order by TimeGenerated desc

// === MDE Live Response sessions without justification ===
//
// WHAT: LR sessions started in last 7d with NO paired investigationId — direct shell without incident linkage.
// WHEN: Weekly responder-activity audit, personnel transitions, LR-credential theft investigation.
// WHY: LR gives SYSTEM-equivalent access — scripts/downloads/kill processes on any device. Every session
//      needs incident OR AIR investigation OR documented IR ticket linkage. Sessions without:
//      (a) responder bypassing process (audit finding), (b) compromised LR credentials (active threat),
//      (c) test/dev work that should be documented separately.
//
// TRIAGE PATH:
//   1. Identify responder UPN from RawJson.requestor field
//   2. Cross-ref with responder's open incident queue at session TimeGenerated
//   3. No match: contact responder for ticket; responder denies → assume compromised credentials
//   4. Pull full LR commands from the Action Center RawJson column for forensic record
//   5. Pair with LrUnsignedScriptsOn.yaml rule (config-side: unsigned scripts even allowed?)
//
// EXPECTED BASELINE: 0-2 sessions/week mature tenant; >5/week = LR-tooling abuse or process gap.
// TUNING: Increase 7d to 30d for monthly compliance. Add requestorOrganizationId for cross-tenant LR.
// MITRE: TA0007 Discovery — T1059 Command and Scripting Interpreter; TA0009 Collection — T1213.
Defender_ActionCenter_CL | where SourceName == 'MDE_ActionCenter_CL' | where TimeGenerated > ago(7d) | extend Type = tostring(parse_json(RawJson).actionType), InvestigationId = tostring(parse_json(RawJson).investigationId) | where Type has "LiveResponse" and isempty(InvestigationId)

// === MDE machine inventory by risk score ===
//
// WHAT: Latest snapshot of every device sorted by RiskScore desc. One row per device with HealthStatus,
//       ExposureLevel, OS info, FirstSeen/LastSeen.
// WHEN: Daily SOC stand-up (top-N drill-down), weekly executive reporting, post-incident scope, pre-patching.
// WHY: RiskScore = active alerts + investigations + suspicious activity. ExposureLevel = TVM weakness rating.
//      RiskScore='High' AND ExposureLevel='High' = SOC's #1 response priority (active threats + unpatched vulns).
//      Foundation stream for Architecture A PerEntityFanout (DeviceTimeline depends on this).
//
// TRIAGE PATH:
//   1. Top 20 by RiskScore desc = IR priorities
//   2. Pivot per machine: Action Center category (alerts), DeviceTimeline source (recent events),
//      Vulnerability Management category (CVE list)
//   3. HealthStatus='Inactive' >7d = stale agent; investigate connectivity or decommissioning
//   4. OsPlatform outliers (e.g., 1 macOS in Windows tenant) = scope review
//
// EXPECTED BASELINE: 5-10% fleet at Medium+ in active tenants; sustained >20% High = incident-in-progress.
// TUNING: Adjust 24h to Inventory cadence if changed. Add `where Tags has 'critical-asset'` for crown-jewel-only.
// MITRE: TA0007 Discovery — T1082 System Information Discovery; T1018 Remote System Discovery.
Defender_EndpointDeviceManagement_CL
| where SourceName == 'MDE_Machines_CL'
| where TimeGenerated > ago(24h)
| summarize arg_max(TimeGenerated, *) by EntityId
| project ComputerDnsName, OsPlatform, OsVersion, HealthStatus, RiskScore, ExposureLevel, LastSeen, FirstSeen
| order by RiskScore desc

// === MDE MDI service account drift ===
//
// WHAT: Changes to MDI service account classifications over 30d — role escalations,
//       service-account-to-user reclassifications, gMSA tagging changes.
// WHEN: Monthly identity governance review, post-AD restructuring, service-account compromise investigation,
//       after any privileged-access-management change.
// WHY: MDI tracks service identities (kerberos delegations, gMSA, SPN-bound accounts) separately from users —
//      different threat model (no interactive logon, no MFA, no offsite). Classification changes mean account
//      behavior or AD attributes changed → could be admin-driven (legit) or attacker-driven (privilege escalation).
//
// TRIAGE PATH:
//   1. Identify account (EntityId) + WHAT changed (FieldName) + values (NewValue vs prior)
//   2. Cross-ref AD change log + change-management tickets
//   3. NEW service-account classification: legitimate promotion or attacker adding SPNs/delegations?
//   4. DROPPED classification: rare; potential credential theft (attacker hiding from MDI)
//   5. Pair with RbacEscalationEvents.yaml for RBAC-side story
//
// EXPECTED BASELINE: 0-3 changes/month mature AD; >10/month = restructuring or sustained attack.
// LICENSE: Requires Microsoft Defender for Identity. Empty in unlicensed tenants.
// MITRE: TA0003 Persistence — T1078.002 Domain Accounts; TA0004 Privilege Escalation — T1098;
//        TA0006 Credential Access — T1558.003 Kerberoasting (SPN tagging changes mask kerberoast).
MDE_Drift_Inventory(30d, 1d) | where StreamName == "MDE_IdentityServiceAccounts_CL"

// === MDE RBAC escalation events ===
//
// WHAT: RBAC role assignments ADDED in last 30d, joined with current state of role record.
//       Returns who gained what permission, when, with latest role definition for context.
// WHEN: Weekly admin-access review, monthly compliance audit, post-IT-onboarding validation,
//       privilege escalation investigation.
// WHY: RBAC additions = canonical privilege-escalation signal. Attacker with admin compromise grants
//      themselves (or backdoor account) Defender admin perms to maintain SOC tooling control.
//      Sustained role-creep creates audit findings AND lateral-movement risk.
//
// TRIAGE PATH:
//   1. Identify principal (EntityId) + role granted (NewValue) + granting admin (correlate ConfigChangesByUpn)
//   2. Verify against access-management ticket (HR onboarding, role-change request)
//   3. No ticket: contact granted user — do they know? Then granting admin — was this them?
//   4. ANY privileged role (Security Administrator, GA-equivalent) without ticket = P1
//   5. Run quarterly: cumulative role-creep audit — top users by total roles added
//
// EXPECTED BASELINE: 1-5 additions/week active org; spike >10/day = mass onboarding or attack.
// TUNING: Adjust 30d for SOC audit cadence. Add OnboardingType filter for emergency vs scheduled.
// MITRE: TA0004 Privilege Escalation — T1078 Valid Accounts (most common); T1098 Account Manipulation;
//        TA0003 Persistence — T1136 Create Account (paired with new principal creation).
//
// Inner join time-bounded to last 30d (matches outer drift parser lookback) — without bound,
// workspace table scan is unbounded → expensive query.
MDE_Drift_Configuration(30d, 1d) | where StreamName == "MDE_UnifiedRbacRoles_CL" and ChangeType == "Added" | join kind=inner (Defender_ConfigurationAndSettings_CL | where TimeGenerated > ago(30d) | where SourceName == 'MDE_UnifiedRbacRoles_CL' | summarize arg_max(TimeGenerated, *) by EntityId) on EntityId

// === MDE security policies (ASR + AV + EDR + Firewall) per platform ===
//
// WHAT: Latest snapshot of every Intune endpoint security policy across all 4 platforms
//       (Windows / Linux / macOS / iOS). Per policy: ASR rules + AV + EDR + Firewall + Disk Encryption +
//       Account Protection + Web Protection. Full body in RawJson.
// WHEN: Quarterly security-config governance review, pre/post Intune migration, audit response (CMMC,
//       FedRAMP, ISO27001), drift investigations.
// WHY: Intune endpoint security policies = central "what protections enforced where" inventory.
//      Without periodic snapshots: can't (a) prove compliance, (b) detect policy weakening (attacker
//      disables ASR rules), (c) compare posture across platforms.
//      Architecture C PerPlatformFanout — Windows + Linux + macOS + iOS in one hunt instead of 4.
//
// TRIAGE PATH:
//   1. Filter `where Platform == 'Linux'` (or other) — per-platform posture review
//   2. `where PolicyType == 'AttackSurfaceReduction'` — verify all ASR rules in Enforce mode (not Audit)
//   3. Diff RuleCount against security-baseline checklist — sudden drops = policy weakening
//   4. parse_json(RawJson).rules for granular per-rule review
//   5. Pair with MDE_Drift_Configuration to detect changes across snapshots
//
// EXPECTED BASELINE: 5-30 policies/platform mature tenants. 0 policies = MDE/Intune integration gap.
// TUNING: Adjust 24h to Configuration cadence. PerPlatformFanout iterates 4 platforms; missing platform
//         rows are empty (not a bug — tenant doesn't deploy that platform).
// MITRE: TA0005 Defense Evasion — T1562 Impair Defenses (govern); TA0007 Discovery — T1518.
Defender_EndpointConfiguration_CL
| where SourceName == 'MDE_SecurityPolicies_CL'
| where TimeGenerated > ago(24h)
| summarize arg_max(TimeGenerated, *) by EntityId
| project PolicyId, PolicyName, PolicyType, Platform, Status, RuleCount, LastModified, RawJson
| order by Platform asc, PolicyType asc

// === MDE silent bypass indicators ===
//
// WHAT: Composite signal — days where BOTH suppression rule added AND PUA protection disabled.
//       Either alone = normal admin; combination same day = highly suspicious.
// WHEN: Daily SOC review, ad-hoc on ransomware/lateral-movement suspicion, post-incident dwell-time analysis.
// WHY: Sophisticated attackers with admin credentials follow predictable preparation playbook:
//      (1) add suppression rules to silence tool-related alerts, (2) disable PUA so dual-use tools
//      (PsExec, BloodHound, certutil-as-downloader) don't get blocked, (3) drop payload.
//      This catches preparation phase BEFORE payload — giving SOC time to respond.
//
// TRIAGE PATH:
//   1. Days flagged: identify admin(s) who made BOTH changes (cross-ref ConfigChangesByUpn.yaml)
//   2. Pull MDE_SuppressionRules_CL recent additions — WHAT alert types suppressed?
//   3. Pull MDE_PUAConfig_CL history — disable with tunable timer or permanent?
//   4. Hunt activity in suppressed categories during disable window: DeviceEvents | where ActionType in (...)
//   5. Suspicious: re-enable PUA + remove suppression + isolate admin session + escalate to IR
//
// EXPECTED BASELINE: 0-1 days/quarter mature tenants; 1+/week = strong attack indicator.
// TUNING: Adjust 7d for slower review. Add other quieting signals: MDE_AlertTuning_CL broadening,
//         MDE_AdvancedFeatures_CL.tamperProtectionEnabled='false', MDE_AntivirusPolicy_CL exclusion adds same day.
// MITRE: TA0005 Defense Evasion — T1562.001 (primary); T1562.006 Indicator Blocking; TA0040 Impact prep.
let drift = MDE_Drift_Configuration(7d, 1h); let suppressions = drift | where StreamName == "MDE_SuppressionRules_CL" and ChangeType == "Added"; let puaOff = drift | where StreamName == "MDE_PUAConfig_CL" and FieldName == "enabled" and NewValue == "false"; union suppressions, puaOff | summarize Events = count() by bin(TimeGenerated, 1d) | where Events >= 2

// === MDE TVM top vulnerable machines + inventory + remediation actions ===
//
// WHAT: Cross-stream TVM hunt — unions latest snapshots of top-vulnerable machines + active CVE inventory
//       + software inventory + remediation tasks. Sortable by stream for prioritization.
// WHEN: Weekly patch-prioritization, monthly compliance posture report, pre-security-audit,
//       post-major-CVE disclosure (Log4Shell, MOVEit, ProxyShell) tenant impact assessment.
// WHY: TVM data split across 4 nodoc endpoints (top-vulnerable / vulns / software / recommendations).
//      SOC value is in the JOIN: "top-10 exposed machines + CVE list + software driver + remediation tasks"
//      is the patch-management orchestration question. Single hunt instead of 4.
//
// TRIAGE PATH:
//   1. Filter `Stream='_topVulnerable' | top 10 by RiskScore` = patch-priority machines
//   2. Pivot to `Stream='_vulnInventory'` to identify their CVE list
//   3. Pivot to `Stream='_softwareInv'` to identify CVE-driving products
//   4. Pivot to `Stream='_recommendations'` for existing remediation tasks (or create new)
//   5. Track in patch-management platform; re-run weekly to measure remediation velocity
//
// EXPECTED BASELINE: Volume scales with tenant. _topVulnerable empty = TVM Premium not licensed.
// TUNING: Adjust 24h to Inventory cadence. Filter by OS platform if patching by platform.
// LICENSE: Requires MDE Plan 2 + TVM Premium add-on. Without it, 4 streams are tenant-gated (zero rows).
// MITRE: TA0007 Discovery — T1518 Software Discovery; T1082; TA0001 — T1190 (vuln inventory feeds priority).
let _topVulnerable = Defender_VulnerabilityManagement_CL
| where SourceName == 'MDE_VulnerableMachines_CL'
| where TimeGenerated > ago(24h)
| summarize arg_max(TimeGenerated, *) by AssetId
| project AssetId, MachineName, CveCount, CriticalCveCount, ExposureScore, RiskScore, OsPlatform;
let _vulnInventory = Defender_VulnerabilityManagement_CL
| where SourceName == 'MDE_VulnerabilityInventory_CL'
| where TimeGenerated > ago(24h)
| summarize arg_max(TimeGenerated, *) by CveId
| project CveId, Severity, CvssV3, AssetCount, ProductName;
let _softwareInv = Defender_VulnerabilityManagement_CL
| where SourceName == 'MDE_SoftwareInventory_CL'
| where TimeGenerated > ago(24h)
| summarize arg_max(TimeGenerated, *) by ProductId
| project ProductId, ProductName, Vendor, AssetCount, VulnerabilityCount, WeaknessCount;
let _recommendations = Defender_VulnerabilityManagement_CL
| where SourceName == 'MDE_RecommendationActions_CL'
| where TimeGenerated > ago(24h)
| summarize arg_max(TimeGenerated, *) by RemediationTaskId
| project RemediationTaskId, Title, Status, Priority, AssetCount, CreatedDate, DueDate;
union withsource=Stream _topVulnerable, _vulnInventory, _softwareInv, _recommendations
| order by Stream asc

// === MDE XSPM chokepoint deltas ===
//
// WHAT: Nodes NEWLY classified as XSPM chokepoints over last 30d. Chokepoints sit on many attack paths
//       to crown jewels — eliminating chokepoints disrupts multiple attack scenarios at once.
// WHEN: Monthly attack-surface-management review, quarterly executive risk reporting,
//       post-IT-restructuring (M&A, role consolidations) when attack paths shift dramatically.
// WHY: XSPM continuously simulates attack paths from internet/email to crown-jewel assets. Some
//      intermediate nodes appear on dozens of paths — chokepoints = highest-leverage hardening targets.
//      New chokepoint = environment change (over-privileged account, sensitive AD placement, lateral
//      movement enabled) that NOW concentrates attacker risk. SOCs not tracking chokepoint deltas
//      miss the shifting attack surface.
//
// TRIAGE PATH:
//   1. New chokepoint EntityId: identify node type (machine / group / identity)
//   2. Pull latest XspmChokePoints record from Exposure Management category for path-count + downstream
//   3. Investigate: WHY chokepoint NOW? AD change? Group membership? New role?
//   4. Cross-ref MDE_Drift_Configuration + RbacEscalationEvents.yaml from same timeframe
//   5. Prioritize: pathCount > 100 = top hardening target; remediate via least-privilege, group cleanup
//
// EXPECTED BASELINE: 0-3 new chokepoints/month stable env; spikes correlate with org changes.
// TUNING: Adjust 30d for executive vs operational cadence.
// LICENSE: XSPM (E5 + security add-on). Zero rows in unlicensed tenants.
// MITRE: TA0043 Reconnaissance — T1595 (defender-side); TA0008 Lateral Movement — T1021 Remote Services.
MDE_Drift_Exposure(30d, 1h) | where StreamName == "MDE_XspmChokePoints_CL" and ChangeType == "Added"

// Phase J D'.3 (2026-05-04): silent-hang detection in XdrLogRaider auth chain.
// Service accounts that have NOT successfully completed an auth chain in
// the last 30 minutes despite the Connector-Heartbeat timer firing.
let staleThresholdMinutes = 30;
// Service accounts seen on AuthChain.Started but not AuthChain.Completed
// since the staleness threshold.
let recentStarts = AppEvents
| where TimeGenerated > ago(2h)
| where Name == 'AuthChain.Started'
| extend Upn = tostring(Properties.Upn);
let recentCompletes = AppEvents
| where TimeGenerated > ago(2h)
| where Name == 'AuthChain.Completed'
| extend Upn = tostring(Properties.Upn)
| summarize LastCompleted = max(TimeGenerated) by Upn;
recentStarts
| summarize Started = count() by Upn
| join kind=leftouter (recentCompletes) on Upn
| extend MinutesSinceLastCompleted = datetime_diff('minute', now(), coalesce(LastCompleted, datetime(1970-01-01)))
| where MinutesSinceLastCompleted > staleThresholdMinutes
| project TimeGenerated = now(), Upn, MinutesSinceLastCompleted, LastCompleted, Started

// B3 (Plan R+++++++++.2 2026-05-08): DLQ depth telemetry from two sources:
//   - xdr.dlq.depth          — emitted by Pop-XdrIngestDlq per pop event (drain rate)
//   - xdr.dlq.pending_count  — emitted by Connector-Heartbeat per 5min (current backlog)
// Either metric exceeding threshold opens the alert; we union them for breadth.
// AppMetrics schema: Sum/Min/Max/ItemCount (no `Value` column).
AppMetrics
| where TimeGenerated > ago(4h)
| where Name in ("xdr.dlq.depth", "xdr.dlq.pending_count")
| summarize MaxValue = max(Max) by Name, bin(TimeGenerated, 1h)
| where MaxValue > 100
| extend AlertReason = strcat(Name, " ", MaxValue, " > 100 entries")
| project TimeGenerated, Name, MaxValue, AlertReason

// Per-stream cost-budget gate. The metric is emitted by Send-ToLogAnalytics
// on every successful ingest batch with the Stream property set so we can
// group per-stream and compare a 1h sliding window against a 7d baseline.
let recentWindow = 1h;
let baselineWindow = 7d;
let spikeFactor = 3.0;
let recent =
AppMetrics
| where TimeGenerated > ago(recentWindow)
| where Name == "xdr.ingest.row_count_per_hour"
| extend Stream = tostring(Properties.Stream)
| summarize RecentRows = sum(Sum) by Stream;
let baseline =
AppMetrics
| where TimeGenerated between (ago(baselineWindow) .. ago(recentWindow))
| where Name == "xdr.ingest.row_count_per_hour"
| extend Stream = tostring(Properties.Stream)
| summarize BaselineRowsPerHour = avg(Sum) by Stream;
recent
| join kind=leftouter baseline on Stream
| extend BaselineRowsPerHour = coalesce(BaselineRowsPerHour, 0.0)
| where BaselineRowsPerHour > 0  // skip cold-start streams (no baseline yet)
| where RecentRows > BaselineRowsPerHour * spikeFactor
| extend SpikeRatio = round(RecentRows / BaselineRowsPerHour, 2)
| extend AlertReason = strcat("Stream ", Stream, " row volume ", SpikeRatio, "x baseline (recent=", RecentRows, " vs avg=", round(BaselineRowsPerHour, 1), "/h)")
| project TimeGenerated = now(), Stream, RecentRows, BaselineRowsPerHour, SpikeRatio, AlertReason

// PARAMETER: $(SERVICE_ACCOUNT_UPN) — bound at ARM deploy time from
// mainTemplate.json deployment parameter. Operator MUST set this in
// createUiDefinition wizard step 2 (auth setup).
let serviceAccountUpn = "$(SERVICE_ACCOUNT_UPN)";
let baselineWindow = 14d;  // Sentinel queryPeriod max is P14D
let detectionWindow = 30m;
// Establish 30-day baseline of countries + IPs the SA normally signs in from
let baseline = SigninLogs
| where TimeGenerated > ago(baselineWindow) and TimeGenerated < ago(detectionWindow)
| where UserPrincipalName =~ serviceAccountUpn
| where ResultType == 0  // successful sign-ins only
| summarize KnownCountries = make_set(LocationDetails.countryOrRegion),
KnownIPs       = make_set(IPAddress);
// Detect anomalies in the last 30 minutes
SigninLogs
| where TimeGenerated > ago(detectionWindow)
| where UserPrincipalName =~ serviceAccountUpn
| extend Country  = tostring(LocationDetails.countryOrRegion)
| extend FailureSignals = case(
ResultType != 0,                                                     "AuthFail-or-MfaChallengeBypass",
Country !in (toscalar(baseline | project KnownCountries)),           "AnomalousCountry",
IPAddress !in (toscalar(baseline | project KnownIPs)),               "AnomalousIP",
""
)
| where FailureSignals != ""
| project TimeGenerated, UserPrincipalName, IPAddress, Country, AppDisplayName,
ResultType, ResultDescription, FailureSignals
